const aliases={"guard":"whirlwind","swordField":"whirlwind","bladeWave":"cleave","quickCut":"dash"};
export function getJobCombat(job){return JOB_COMBAT[job]||null;}
export function getJobSkillDescription(job,id,fallback=''){return JOB_COMBAT[job]?.skills[aliases[id]||id]||fallback;}
export function recommendedSkills(job,level,fallback){return Object.keys(JOB_COMBAT[job]?.skills||{}).length?Object.keys(JOB_COMBAT[job].skills):[...fallback];}
export function getCareerWeapon(game,index){
 const h=HERO_PROGRESSIONS[game.heroId||game.player?.heroId];if(!h)return null;
 const tier=Math.max(0,h.jobs.indexOf(game.heroJob||game.player?.job));let description=h.basic[tier][Math.min(3,index)];
 if(index>=3){const split=description.match(/^A[：:]?([\s\S]*?)[；;]B[：:]?([\s\S]*)$/);if(split)description=split[index===3?1:2];}
 return [h.tierIdentity[tier]+' · '+['起式','衍式','化式','清群','破强'][index],description];
}
